from common import *
R=[{'sourceId':'vinh','locator':'Chương 2–7; mục lục bản scan ở trang PDF 5–7'},{'sourceId':'lax','locator':'Các chương Linear Space, Linear Maps, Determinant, Spectral Theory'},{'sourceId':'solomon','locator':'Các mục Vector Spaces, Linear Systems, Least Squares, Eigenvalues và SVD'}]
s=[]
s.append(S('systems','Hệ phương trình tuyến tính và khử Gauss',r'Hệ $Ax=b$ được biểu diễn bằng ma trận mở rộng $[A\mid b]$. Các phép đổi hàng, nhân hàng với số khác 0 và cộng bội hàng khác bảo toàn tập nghiệm. Dạng bậc thang cho biết cột trụ, biến tự do và tính tương thích. § Hệ có nghiệm khi $\operatorname{rank}A=\operatorname{rank}[A\mid b]$; nếu có nghiệm, số biến tự do bằng n trừ hạng. Một hàng $[0\cdots0\mid c]$ với $c\ne0$ chứng tỏ vô nghiệm.',r'Lập ma trận mở rộng. § Khử bằng phép biến đổi hàng có ghi chép. § Đọc điều kiện tương thích và tham số hóa biến tự do.','Không dùng phép nhân hàng với 0 vì sẽ làm mất phương trình.',[
E(r'Giải $x+y=3$, $2x-y=0$.',r'Cộng hai phương trình cho $3x=3$. § Suy ra $x=1$ rồi thế vào phương trình đầu được $y=2$. § Kiểm tra $2\cdot1-2=0$.',r'$(x,y)=(1,2)$.','Khử một biến trước giúp hệ tam giác hóa.'),
E(r'Giải $x+2y=4$, $2x+4y=8$.',r'Phương trình hai là hai lần phương trình một. § Chỉ có một phương trình độc lập với hai ẩn. § Đặt $y=t$, suy ra $x=4-2t$.',r'$(x,y)=(4-2t,t)$, $t\in\mathbb R$.','Một hàng 0 sau khử có thể tạo biến tự do, không tự tạo vô nghiệm.'),
E(r'Xét $x+2y=4$, $2x+4y=9$.',r'Lấy hàng hai trừ hai lần hàng một. § Vế trái trở thành 0 nhưng vế phải bằng 1. § Đẳng thức 0 bằng 1 là bất khả thi.',r'Hệ vô nghiệm.','Hàng mâu thuẫn ở ma trận mở rộng là chứng cứ vô nghiệm.'),
E(r'Giải $x+y+z=2$, $y+z=1$.',r'Trừ phương trình hai khỏi phương trình một cho $x=1$. § Đặt biến tự do $z=t$. § Phương trình hai cho $y=1-t$; thế lại cả hai phương trình đều đúng.',r'$(x,y,z)=(1,1-t,t)$.','Số phương trình ít hơn số ẩn có thể tạo một họ nghiệm affine.'),
E(r'Tìm a để $x+y=1$, $x+ay=2$ có nghiệm duy nhất.',r'Lấy phương trình hai trừ phương trình một: $(a-1)y=1$. § Nếu $a\ne1$, có duy nhất $y=1/(a-1)$ rồi xác định x. § Nếu $a=1$, hệ cho mâu thuẫn $0=1$.',r'Nghiệm duy nhất khi $a\ne1$.','Tham số tại vị trí trụ phải được tách riêng trước khi chia.')],R))
s.append(S('matrix-lu','Ma trận, nghịch đảo và phân tích LU',r'Tích ma trận biểu diễn hợp các phép tuyến tính và nói chung không giao hoán. Ma trận vuông khả nghịch khi tồn tại nghịch đảo hai phía; khi đó mỗi hệ Ax=b có nghiệm duy nhất. § Khử Gauss có thể viết thành $PA=LU$, trong đó P mô tả đổi hàng, L tam giác dưới và U tam giác trên. Giải nhiều vế phải nên dùng phân tích thay vì tính nghịch đảo tường minh; lựa chọn trụ ảnh hưởng độ ổn định số.',r'Kiểm tra kích thước phép nhân. § Thực hiện khử hoặc phân tích tam giác. § Kiểm tra bằng nhân lại và thế nghiệm.','Nghịch đảo tích đảo ngược thứ tự: $(AB)^{-1}=B^{-1}A^{-1}$.',[
E(r'Nhân $A=\begin{pmatrix}1&2\\0&1\end{pmatrix}$ với $B=\begin{pmatrix}1&0\\3&1\end{pmatrix}$.',r'Mỗi phần tử tích lấy hàng của A nhân cột của B. § Tính hàng đầu được $(7,2)$; hàng hai được $(3,1)$. § Tính BA cho hàng đầu $(1,2)$, khác AB.',r'$AB=\begin{pmatrix}7&2\\3&1\end{pmatrix}\ne BA$.','Ví dụ cụ thể cho thấy không thể đổi thứ tự nhân ma trận.'),
E(r'Tìm nghịch đảo của $A=\begin{pmatrix}2&1\\1&1\end{pmatrix}$.',r'Định thức bằng $2\cdot1-1\cdot1=1$. § Công thức ma trận 2 nhân 2 cho $A^{-1}=\begin{pmatrix}1&-1\\-1&2\end{pmatrix}$. § Nhân A với ma trận này cho ma trận đơn vị.',r'$A^{-1}=\begin{pmatrix}1&-1\\-1&2\end{pmatrix}$.','Luôn có thể xác nhận nghịch đảo bằng phép nhân.'),
E(r'Phân tích LU của $A=\begin{pmatrix}2&1\\4&3\end{pmatrix}$ không đổi hàng.',r'Hệ số khử phần tử dưới trụ là $4/2=2$. § Hàng hai trừ hai lần hàng một cho $(0,1)$. § Lưu hệ số 2 vào L rồi nhân lại để kiểm tra.',r'$L=\begin{pmatrix}1&0\\2&1\end{pmatrix}$, $U=\begin{pmatrix}2&1\\0&1\end{pmatrix}$.','L chứa các hệ số khử, U chứa kết quả khử.'),
E(r'Dùng LU trên giải $Ax=(3,7)^T$.',r'Giải $Ly=b$: $y_1=3$, $2y_1+y_2=7$ nên $y_2=1$. § Giải $Ux=y$: $x_2=1$, $2x_1+x_2=3$. § Suy ra $x_1=1$ và kiểm tra Ax=b.',r'$x=(1,1)^T$.','Thay tiến và thay lùi tái sử dụng một phân tích cho nhiều vế phải.'),
E(r'Vì sao $A=\begin{pmatrix}1&2\\2&4\end{pmatrix}$ không khả nghịch?',r'Hàng hai là hai lần hàng một. § Vectơ $v=(-2,1)^T$ khác 0 nhưng Av=0. § Nếu A có nghịch đảo thì nhân hai vế sẽ cho v=0, mâu thuẫn.',r'A suy biến.','Một vectơ không trong kernel đã đủ chứng minh không khả nghịch.')],R))
s.append(S('spaces-bases','Không gian vectơ, cơ sở và tọa độ',r'Không gian con phải chứa 0 và đóng với cộng, nhân vô hướng. Tập sinh tạo ra mọi vectơ bằng tổ hợp tuyến tính; độc lập tuyến tính nghĩa là tổ hợp bằng 0 chỉ có hệ số 0. § Cơ sở vừa sinh vừa độc lập, và mọi cơ sở hữu hạn của cùng không gian có cùng số phần tử gọi là số chiều. Tọa độ của vectơ phụ thuộc cơ sở, còn vectơ hình học không thay đổi.',r'Kiểm tra đóng hoặc mô tả qua hệ tuyến tính. § Khử để chọn tập độc lập. § Giải hệ tìm tọa độ theo cơ sở đã chỉ định.','Một tập chứa 0 không thể độc lập tuyến tính nếu 0 là một phần tử của tập.',[
E(r'Tập $W=\{(x,y,z):x+y+z=0\}$ có là không gian con?',r'Vectơ 0 thỏa điều kiện. § Nếu u,v có tổng tọa độ bằng 0 thì u+v cũng vậy; nhân vô hướng cũng bảo toàn. § Viết $(x,y,z)=x(1,0,-1)+y(0,1,-1)$.',r'W là không gian con, có cơ sở $\{(1,0,-1),(0,1,-1)\}$, chiều 2.','Mô tả nghiệm thuần nhất cho một cách nhận diện không gian con.'),
E(r'Tập $x+y=1$ trong $\mathbb R^2$ có là không gian con?',r'Vectơ 0 không thỏa phương trình. § Điều kiện cần chứa 0 đã bị vi phạm. § Đây là một đường affine, không đi qua gốc.',r'Không phải không gian con.','Không cần kiểm tra thêm các tính đóng khi một điều kiện cần đã sai.'),
E(r'Hai vectơ $(1,1)$ và $(1,-1)$ có là cơ sở của $\mathbb R^2$?',r'Giải $a(1,1)+b(1,-1)=0$. § Hệ $a+b=0$, $a-b=0$ cho a=b=0. § Hai vectơ độc lập trong không gian chiều 2 tạo thành cơ sở.',r'Có.','Số lượng đúng bằng số chiều kết hợp độc lập là đủ để có cơ sở.'),
E(r'Tìm tọa độ $(3,1)$ theo cơ sở ở ví dụ trước.',r'Viết $(3,1)=a(1,1)+b(1,-1)$. § Giải $a+b=3$, $a-b=1$ được a=2,b=1. § Thay lại $2(1,1)+(1,-1)=(3,1)$.',r'Tọa độ theo cơ sở là $(2,1)$.','Không nhầm tọa độ mới với tọa độ chuẩn ban đầu.'),
E(r'Tìm số chiều không gian đa thức thực bậc không quá 2.',r'Mỗi đa thức có dạng $a+bx+cx^2$. § Các đa thức $1,x,x^2$ sinh ra tất cả và độc lập do các hệ số phải bằng 0 khi đa thức 0. § Có đúng ba phần tử trong cơ sở.',r'Số chiều bằng 3.','Vectơ của không gian tuyến tính không nhất thiết là cột số.')],R))
s.append(S('maps-rank','Ánh xạ tuyến tính, kernel và định lý hạng–không gian-không',r'Ánh xạ T tuyến tính khi $T(au+bv)=aT(u)+bT(v)$. Kernel là các đầu vào có ảnh 0; ảnh là tập mọi đầu ra. Cả hai là không gian con. § Với miền nguồn hữu hạn chiều, $\dim\ker T+\dim\operatorname{im}T=\dim V$. Ma trận của T theo cơ sở có các cột là tọa độ ảnh các vectơ cơ sở. Đổi cơ sở ở nguồn/đích phải được theo dõi bằng ma trận chuyển tọa độ.',r'Tính ảnh của cơ sở. § Giải hệ kernel và chọn các cột trụ cho ảnh. § Kiểm tra tổng chiều bằng chiều miền nguồn.','Ánh xạ affine có số hạng hằng khác 0 không phải ánh xạ tuyến tính.',[
E(r'$T(x,y)=(x+y,2x+2y)$. Tìm ma trận, kernel và hạng.',r'Ảnh hai vectơ cơ sở là $(1,2)$ và $(1,2)$. § Kernel thỏa x+y=0 nên là đường sinh bởi $(1,-1)$. § Ảnh sinh bởi $(1,2)$ nên hạng 1.',r'$[T]=\begin{pmatrix}1&1\\2&2\end{pmatrix}$; nullity 1, rank 1.','Tổng hạng và chiều kernel bằng 2.'),
E(r'Kiểm tra $T(x)=x+1$ trên số thực có tuyến tính không.',r'Mọi ánh xạ tuyến tính phải gửi 0 tới 0. § Ở đây T(0)=1. § Vì một điều kiện cần bị vi phạm, T không tuyến tính.',r'Không tuyến tính.','Đây là phép tịnh tiến, thuộc loại affine.'),
E(r'Phép đạo hàm $D:P_2\to P_1$ có kernel và hạng thế nào?',r'$D(a+bx+cx^2)=b+2cx$. § Kernel gồm các đa thức hằng, chiều 1. § Mọi đa thức bậc không quá 1 có nguyên hàm trong $P_2$, nên ảnh chiều 2.',r'Nullity 1 và rank 2, tổng bằng $\dim P_2=3$.','Định lý hạng cũng dùng cho ánh xạ giữa các không gian hàm.'),
E(r'Chiếu $T(x,y,z)=(x,y,0)$: tìm T bình phương.',r'Áp dụng một lần loại tọa độ thứ ba. § Áp dụng lần nữa không thay đổi kết quả. § Vì vậy $T(T(v))=T(v)$ với mọi v.',r'$T^2=T$, kernel sinh bởi $(0,0,1)$.','Tính lũy đẳng là dấu hiệu đại số của phép chiếu.'),
E(r'Một ánh xạ từ $\mathbb R^5$ sang $\mathbb R^3$ có hạng 3. Kernel có chiều bao nhiêu?',r'Miền nguồn có chiều 5. § Dùng rank–nullity: $3+\dim\ker T=5$. § Suy ra kernel chiều 2; hạng bằng chiều đích nên T toàn ánh.',r'$\dim\ker T=2$.','Không thể đơn ánh từ miền chiều 5 vào đích chiều 3.')],R))
s.append(S('determinants','Định thức, định hướng và khả nghịch',r'Định thức là hàm đa tuyến tính luân phiên theo các hàng hoặc cột, chuẩn hóa det I=1. Nó đổi dấu khi đổi hai hàng, nhân theo hệ số khi nhân một hàng, và không đổi khi cộng bội hàng khác. § Với ma trận vuông, det khác 0 tương đương khả nghịch. Tích các phần tử đường chéo của ma trận tam giác là định thức. Trong hình học, trị tuyệt đối định thức đo hệ số biến đổi thể tích, còn dấu cho định hướng.',r'Dùng biến đổi hàng ít tốn phép tính. § Theo dõi đổi dấu và hệ số. § Kiểm tra bằng hạng hoặc ý nghĩa thể tích.','Cộng một bội hàng khác không đổi định thức, nhưng nhân cả hàng thì có đổi.',[
E(r'Tính det của $\begin{pmatrix}3&2\\1&4\end{pmatrix}$.',r'Dùng công thức đường chéo chính trừ phụ. § $3\cdot4-2\cdot1=10$. § Vì khác 0 nên ma trận khả nghịch.',r'Định thức bằng 10.','Trong hai chiều, 10 cũng là hệ số diện tích có dấu.'),
E(r'Tính định thức ma trận tam giác đường chéo $2,-1,5$.',r'Các phần tử dưới đường chéo đều bằng 0. § Định thức bằng tích các phần tử đường chéo. § Nhân $2\cdot(-1)\cdot5=-10$.',r'$-10$.','Không cần khai triển nhiều phần bù đại số cho một ma trận tam giác.'),
E(r'Nếu det A=7, đổi hai hàng của A được B. Tính det B.',r'Định thức có tính luân phiên theo các hàng. § Đổi đúng một cặp hàng nhân định thức với $-1$. § Áp dụng vào giá trị đã cho.',r'$\det B=-7$.','Đổi hàng trong khử Gauss phải được ghi vào dấu định thức.'),
E(r'Nếu A là ma trận 3 nhân 3 và det A=2, tính det(2A).',r'Nhân A với 2 nghĩa là nhân từng hàng với 2. § Có ba hàng nên định thức nhân với $2^3$. § Kết quả là $8\cdot2=16$.',r'$\det(2A)=16$.','Hệ số toàn ma trận được nâng lên lũy thừa số chiều.'),
E(r'Tính diện tích hình bình hành sinh bởi $(2,1)$ và $(1,3)$.',r'Lập ma trận có hai vectơ làm cột. § Định thức là $2\cdot3-1\cdot1=5$. § Lấy trị tuyệt đối để có diện tích không âm.',r'Diện tích bằng 5.','Đổi thứ tự hai vectơ đổi hướng nhưng không đổi diện tích.')],R))
s.append(S('eigenvalues','Trị riêng, chéo hóa và động lực tuyến tính',r'Trị riêng thỏa $Av=\lambda v$ với v khác 0. Chúng là nghiệm của $\det(A-\lambda I)=0$. Ma trận chéo hóa được khi có một cơ sở gồm các vectơ riêng. § Nếu $A=PDP^{-1}$ thì $A^n=PD^nP^{-1}$. Bội đại số của một trị riêng có thể lớn hơn số chiều không gian riêng; đây là nguyên nhân không chéo hóa được. Không được coi vectơ 0 là vectơ riêng.',r'Tính đa thức đặc trưng. § Tìm từng kernel của $A-\lambda I$. § Đếm vectơ riêng độc lập trước khi chéo hóa.','Có đủ số nghiệm của đa thức đặc trưng kể cả bội không đảm bảo chéo hóa.',[
E(r'Tìm trị riêng của $\begin{pmatrix}2&0\\0&5\end{pmatrix}$.',r'Ma trận đã chéo nên hai vectơ cơ sở là vectơ riêng. § Các hệ số nhân tương ứng là 2 và 5. § Đa thức đặc trưng $(2-\lambda)(5-\lambda)$ xác nhận kết quả.',r'Trị riêng 2 và 5.','Với ma trận chéo, lũy thừa chỉ cần nâng các phần tử đường chéo.'),
E(r'Tìm trị riêng của $A=\begin{pmatrix}2&1\\1&2\end{pmatrix}$.',r'Đa thức đặc trưng là $(2-\lambda)^2-1$. § Nghiệm là 3 và 1. § Vectơ $(1,1)$ ứng với 3, $(1,-1)$ ứng với 1 và độc lập.',r'A chéo hóa được với hai trị riêng 3,1.','Ma trận đối xứng có thể chọn các vectơ riêng trực giao.'),
E(r'$A=\begin{pmatrix}1&1\\0&1\end{pmatrix}$ có chéo hóa được không?',r'Chỉ có trị riêng 1 với bội đại số 2. § Kernel của A-I thỏa y=0, chỉ có chiều 1. § Thiếu một vectơ riêng độc lập nên không thể tạo cơ sở riêng.',r'Không chéo hóa được.','Bội hình học khác bội đại số là một chứng cứ thiếu chéo hóa.'),
E(r'Giải $x_{n+1}=Ax_n$, $A=\operatorname{diag}(1/2,2)$, $x_0=(4,1)$.',r'Lặp cho $x_n=A^nx_0$. § Hai tọa độ lần lượt nhân với $(1/2)^n$ và $2^n$. § Tọa độ đầu giảm về 0, tọa độ sau tăng không bị chặn.',r'$x_n=(4\cdot2^{-n},2^n)$.','Trị riêng có độ lớn khác 1 tạo các hướng ổn định hoặc tăng trưởng.'),
E(r'Với A ở ví dụ đối xứng, tính $A^n(1,1)^T$.',r'Vectơ $(1,1)^T$ là vectơ riêng trị riêng 3. § Áp dụng A một lần nhân với 3. § Quy nạp qua n lần cho hệ số $3^n$.',r'$A^n(1,1)^T=3^n(1,1)^T$.','Không cần tính toàn bộ ma trận lũy thừa khi đầu vào là vectơ riêng.')],R))
s.append(S('orthogonality','Tích vô hướng, trực giao hóa và bình phương tối thiểu',r'Tích vô hướng tạo chuẩn $\|x\|=\sqrt{\langle x,x\rangle}$ và khái niệm trực giao. Chiếu lên không gian cột của A tìm vectơ gần b nhất; phần dư trực giao các cột nên thỏa $A^T(A\hat x-b)=0$. § Gram–Schmidt tạo cơ sở trực chuẩn bằng cách trừ các thành phần chiếu. QR thường ổn định số hơn giải phương trình chuẩn; $A^TA$ chỉ khả nghịch nếu các cột A độc lập.',r'Tính các tích vô hướng. § Trừ thành phần chiếu hoặc giải hệ bình phương tối thiểu. § Kiểm tra phần dư trực giao.','Không dùng công thức nghịch đảo của A chuyển vị A khi các cột phụ thuộc.',[
E(r'Chiếu $b=(3,4)$ lên đường sinh bởi $u=(1,0)$.',r'Hệ số chiếu là $(b\cdot u)/(u\cdot u)=3$. § Vectơ chiếu bằng $(3,0)$. § Phần dư $(0,4)$ trực giao với u.',r'Chiếu là $(3,0)$, khoảng cách bằng 4.','Phần dư vuông góc xác nhận điểm gần nhất.'),
E(r'Chiếu $(1,2)$ lên đường sinh bởi $(1,1)$.',r'Tích vô hướng với u là 3, còn $u\cdot u=2$. § Hệ số chiếu bằng $3/2$. § Phần dư $(-1/2,1/2)$ có tích vô hướng 0 với u.',r'Chiếu là $(3/2,3/2)$.','Tọa độ chiếu không nhất thiết là các tọa độ nguyên.'),
E(r'Trực chuẩn hóa $(1,1)$ và $(1,0)$.',r'Vectơ đầu chuẩn hóa thành $q_1=(1,1)/\sqrt2$. § Trừ chiếu của $(1,0)$ lên q1 được $(1/2,-1/2)$. § Chuẩn hóa phần dư thành $q_2=(1,-1)/\sqrt2$.',r'$q_1,q_2$ là một cơ sở trực chuẩn.','Bước trừ chiếu tạo trực giao; bước chia chuẩn tạo độ dài 1.'),
E(r'Tìm hằng số c gần ba số 1,2,6 nhất theo tổng bình phương.',r'Mục tiêu $F(c)=(c-1)^2+(c-2)^2+(c-6)^2$. § Đạo hàm $6c-18=0$ cho c=3. § Vì đạo hàm bậc hai bằng 6 dương, đây là cực tiểu duy nhất.',r'$c=3$, tức trung bình mẫu.','Trung bình xuất hiện như phép chiếu lên không gian các vectơ hằng.'),
E(r'Khớp đường thẳng $y=a+bx$ qua dữ liệu $(0,1),(1,2),(2,2)$.',r'Phương trình chuẩn là $3a+3b=5$, $3a+5b=6$. § Trừ hai phương trình cho $b=1/2$, rồi $a=7/6$. § Phần dư tại ba điểm là $(-1/6,1/3,-1/6)$, có tổng 0 và tích có trọng số x bằng 0.',r'$\hat y=7/6+x/2$.','Kiểm tra trực giao phần dư là cách xác nhận nghiệm bình phương tối thiểu.')],R))
s.append(S('svd-quadratic','Định lý phổ, SVD và dạng toàn phương',r'Ma trận đối xứng thực có cơ sở trực chuẩn gồm các vectơ riêng: $A=Q\Lambda Q^T$. Dạng toàn phương $x^TAx$ xác định dương khi mọi trị riêng dương. § SVD $A=U\Sigma V^T$ áp dụng cả ma trận chữ nhật; giá trị kỳ dị là căn các trị riêng không âm của $A^TA$. Bỏ các thành phần kỳ dị nhỏ tạo xấp xỉ hạng thấp; cần phân biệt trị riêng có dấu với giá trị kỳ dị luôn không âm.',r'Kiểm tra đối xứng hoặc lập A chuyển vị A. § Tính trị riêng và chuẩn hóa vectơ. § Diễn giải độ dương, hạng hoặc sai số xấp xỉ.','Giá trị kỳ dị không phải luôn bằng trị riêng; với ma trận đối xứng là trị tuyệt đối của trị riêng.',[
E(r'Xét độ dương của $q(x,y)=2x^2+2xy+2y^2$.',r'Ma trận đối xứng là $\begin{pmatrix}2&1\\1&2\end{pmatrix}$. § Hai trị riêng là 3 và 1, đều dương. § Vì vậy q dương với mọi vectơ khác 0; cũng có thể viết $q=(x+y)^2+x^2+y^2$.',r'Dạng toàn phương xác định dương.','Hai cách kiểm tra đại số độc lập làm kết luận đáng tin hơn.'),
E(r'Phân loại $q=x^2-y^2$.',r'Ma trận chéo có trị riêng 1 và $-1$. § Tại $(1,0)$, q dương; tại $(0,1)$, q âm. § Có cả hai dấu nên dạng không xác định.',r'Dạng toàn phương không xác định.','Dấu trái nhau có thể được chứng minh bằng hai vectơ thử.'),
E(r'Tìm giá trị kỳ dị của $A=\operatorname{diag}(3,-2)$.',r'$A^TA=\operatorname{diag}(9,4)$. § Lấy căn các trị riêng 9 và 4. § Nhận 3 và 2, không nhận giá trị âm.',r'Các giá trị kỳ dị là 3,2.','Dấu âm được hấp thụ vào vectơ kỳ dị chứ không vào Sigma.'),
E(r'Tìm xấp xỉ hạng 1 tốt nhất theo chuẩn Frobenius của $A=\operatorname{diag}(5,1)$.',r'Hai giá trị kỳ dị là 5 và 1. § Giữ thành phần lớn nhất, bỏ thành phần bằng 1. § Ma trận sai số có duy nhất phần tử 1 ở đường chéo, nên chuẩn Frobenius bằng 1.',r'$A_1=\operatorname{diag}(5,0)$, sai số 1.','SVD giải thích vì sao giữ thành phần năng lượng lớn nhất cho xấp xỉ tốt nhất.'),
E(r'Tìm giá trị lớn nhất của $x^TAx$ khi $\|x\|=1$, với $A=\operatorname{diag}(4,1)$.',r'Với $x=(u,v)$, biểu thức bằng $4u^2+v^2$ và $u^2+v^2=1$. § Viết thành $1+3u^2\le4$. § Dấu bằng khi $v=0$, $u=\pm1$.',r'Giá trị lớn nhất bằng 4, là trị riêng lớn nhất.','Thương Rayleigh nối tối ưu có ràng buộc với lý thuyết phổ.')],R))
save('mth-309',['Đại số phổ thông, hệ phương trình và vectơ'],['Giải hệ và mô tả không gian nghiệm','Phân tích ánh xạ qua hạng, định thức và trị riêng','Dùng trực giao, bình phương tối thiểu và SVD'],s)
